<?php
require_once __DIR__ . '/_layout.php';
$id = filter_input(INPUT_GET, 'edit', FILTER_VALIDATE_INT); $edit = null;
if ($id) { $s = db()->prepare('SELECT activity_id AS id, cleanup_activities.* FROM cleanup_activities WHERE activity_id=?'); $s->execute([$id]); $edit = $s->fetch() ?: null; }
$items = db()->query('SELECT activity_id AS id, cleanup_activities.* FROM cleanup_activities ORDER BY activity_date DESC')->fetchAll();
admin_header('Manage clean-up activities');
?>
<div class="row g-3"><div class="col-xl-5"><form class="surface-card" action="../actions/admin.php" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="save_activity"><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?>"><h2 class="h6 fw-bold"><?= $edit ? 'Edit activity' : 'Add an activity' ?></h2><div class="mb-3"><label class="form-label">Activity title</label><input class="form-control" name="activity_title" required maxlength="180" value="<?= e($edit['activity_title'] ?? '') ?>"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4" required><?= e($edit['description'] ?? '') ?></textarea></div><div class="mb-3"><label class="form-label">Location</label><input class="form-control" name="location" required maxlength="180" value="<?= e($edit['location'] ?? '') ?>"></div><div class="mb-3"><label class="form-label">Date and time</label><input class="form-control" type="datetime-local" name="activity_date" required value="<?= isset($edit['activity_date']) ? e(date('Y-m-d\TH:i', strtotime($edit['activity_date']))) : '' ?>"></div><div class="mb-3"><label class="form-label">Image (optional)</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach (['Upcoming','Completed','Cancelled'] as $status): ?><option <?= ($edit['status'] ?? 'Upcoming') === $status ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select></div><div class="d-flex gap-2"><button class="btn btn-primary rounded-pill">Save activity</button><?php if ($edit): ?><a class="btn btn-outline-secondary rounded-pill" href="manage-activities.php">Cancel</a><?php endif; ?></div></form></div>
<div class="col-xl-7"><section class="surface-card"><h2 class="h6 fw-bold">Published activities</h2><div class="admin-table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Activity</th><th>Date</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['activity_title']) ?></td><td><?= e(date('M j, Y', strtotime($item['activity_date']))) ?></td><td><?= e($item['location']) ?></td><td><?= e($item['status']) ?></td><td class="text-nowrap"><a class="btn btn-outline-primary btn-sm" href="manage-activities.php?edit=<?= (int) $item['id'] ?>">Edit</a><form class="d-inline" method="post" action="../actions/admin.php"><?= csrf_field() ?><input type="hidden" name="action" value="delete_activity"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn btn-outline-danger btn-sm" data-confirm="Delete this activity?">Delete</button></form></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="5" class="text-secondary">No activities yet.</td></tr><?php endif; ?></tbody></table></div></section></div></div>
<?php admin_footer(); ?>
